function renderDependencies(task,card){const panel=$('.dependency-panel',card),list=$('.dependency-list',card),form=$('.dependency-form',card);panel.hidden=!canWriteTasks()&&!task.dependencies?.length;list.replaceChildren();for(const dependency of task.dependencies||[]){const row=document.createElement('div');row.className='dependency';row.dataset.satisfied=String(dependency.satisfied);const label=document.createElement('span');label.textContent=`${dependency.satisfied?'Ready':'Waiting'} · ${dependency.hidden?'A task you cannot see':dependency.blocked_by_title}`;const status=document.createElement('span');status.textContent=dependency.blocked_by_status;row.append(label,status);if(canWriteTasks()&&!['done','cancelled'].includes(task.status)){const remove=document.createElement('button');remove.type='button';remove.className='text-button';remove.textContent='Remove';remove.addEventListener('click',()=>removeDependency(task,dependency,remove));row.append(remove)}list.append(row)}form.hidden=!canWriteTasks()||['done','cancelled'].includes(task.status);const linked=new Set([task.id,...(task.dependencies||[]).map(dependency=>dependency.blocked_by_task_id)]);form.elements.blocked_by_task_id.replaceChildren(option('','Choose a task…'),...openTasks().filter(other=>!linked.has(other.id)).sort((a,b)=>a.title.localeCompare(b.title)).map(other=>option(other.id,other.title)));form.addEventListener('submit',event=>addDependency(task,event))}
