function renderRequirements(task,card){const panel=$('.requirements-panel',card),list=$('.requirements-list',card),form=$('.requirements-form',card);panel.hidden=!canWriteTasks()&&!task.requirements?.length;list.replaceChildren();for(const requirement of task.requirements||[]){const chip=document.createElement('code');chip.textContent=requirement;list.append(chip)}form.hidden=!canWriteTasks()||['done','cancelled'].includes(task.status);form.elements.requirements.value=(task.requirements||[]).join(', ');form.addEventListener('submit',event=>saveRequirements(task,event));const suggestions=$('.requirement-suggestions',panel);renderRequirementSuggestions(suggestions,form.elements.requirements);form.elements.requirements.addEventListener('input',()=>renderRequirementSuggestions(suggestions,form.elements.requirements));panel.addEventListener('toggle',()=>{if(panel.open&&!form.hidden)loadWorkerCapabilities().then(()=>renderRequirementSuggestions(suggestions,form.elements.requirements))})}
