async function loadWorkerCapabilities(){if(!canWriteTasks())return;try{const data=await api('/api/v1/worker-capabilities');state.workerCapabilities=(data.capabilities||[]).map(capability=>({capability,description:data.descriptions?.[capability]||''}))}catch{}}
// Suggestions only: free text stays valid so a profile can be queued before its worker deploys.
function renderRequirementSuggestions(container,input){const chosen=requirementList(input.value),buttons=state.workerCapabilities.filter(item=>!chosen.includes(item.capability)).map(({capability,description})=>{const button=document.createElement('button'),token=document.createElement('code');button.type='button';button.className='text-button requirement-suggestion';token.textContent=`+ ${capability}`;button.append(token);button.setAttribute('aria-label',description?`Add requirement ${capability}: ${description}`:`Add requirement ${capability}`);if(description){const text=document.createElement('span');text.className='requirement-description';text.textContent=description;button.append(text);button.title=description}button.addEventListener('click',()=>{input.value=addRequirement(input.value,capability);input.dispatchEvent(new Event('input',{bubbles:true}));renderRequirementSuggestions(container,input);input.focus()});return button});const label=document.createElement('span');label.textContent='Live workers advertise';container.replaceChildren(...(buttons.length?[label,...buttons]:[]));container.hidden=!buttons.length}
