function messageAuthor(task,message){const run=task.runs?.find(candidate=>candidate.id===message.author_run_id);return run?.callsign||(message.author===state.identity?'You':message.author)}
function receiptLabel(task,message){if(!message.receipts?.length)return message.requires_ack?'Pending acknowledgement':message.target_run_id?'Pending observation':'';const receipts=message.receipts.map(receipt=>{const run=task.runs?.find(candidate=>candidate.id===receipt.run_id);return {label:run?.callsign||receipt.observer,receipt}});const acknowledged=receipts.filter(item=>item.receipt.acknowledged_at);if(acknowledged.length)return `Acknowledged by ${acknowledged.map(item=>item.label).join(', ')}`;return `Observed by ${receipts.map(item=>item.label).join(', ')}`}
