function renderEscalations(task,card){const container=$('.escalation-list',card),items=state.escalations.get(task.id)||[];container.replaceChildren();for(const escalation of items){const panel=document.createElement('section');panel.className='escalation';panel.dataset.blocking=String(escalation.blocking);const header=document.createElement('div');header.className='escalation-header';const kind=document.createElement('strong');kind.textContent=escalation.blocking?'Blocking decision':'Question';const status=document.createElement('span');status.textContent=escalation.status;header.append(kind,status);const question=document.createElement('p');question.className='escalation-question';const asked=escalationMessage(task.id,escalation.question_message_id);question.textContent=asked?.body||'Question unavailable';panel.append(header,question);if(escalation.options?.length){const choices=document.createElement('ul');choices.className='escalation-options';for(const value of escalation.options){const choice=document.createElement('li');choice.textContent=value;choices.append(choice)}panel.append(choices)}if(escalation.recommendation){const recommendation=document.createElement('p');recommendation.className='escalation-recommendation';recommendation.textContent=`Recommendation: ${escalation.recommendation}`;panel.append(recommendation)}const policy=[asked&&`Asked by ${messageAuthor(task,asked)} ${relativeTime(asked.created_at)}`,escalationPolicy(escalation)].filter(Boolean).join(' · ');if(policy){const line=document.createElement('p');line.className='escalation-policy';line.textContent=policy;panel.append(line)}if(escalation.status==='answered'){const answer=document.createElement('p');answer.className='escalation-answer';const answered=escalationMessage(task.id,escalation.answer_message_id),body=answered?.body||'Answer recorded';answer.textContent=`Decision${answered?` by ${messageAuthor(task,answered)}`:''}${escalation.selected_option?` · ${escalation.selected_option}`:''}: ${body}${escalation.delegated_by?` (forwarded by ${escalation.delegated_by})`:''}`;panel.append(answer)}else if(escalation.status==='expired'){const expired=document.createElement('p');expired.className='escalation-policy';expired.textContent='Expired without an answer. Resume or requeue the task so the agent can ask again.';panel.append(expired)}else if(canWriteTasks()){const form=document.createElement('form');form.className='escalation-answer-form';form.dataset.draftKey=escalation.id;if(escalation.options?.length){const choiceLabel=document.createElement('label');choiceLabel.textContent='Selected option';const select=document.createElement('select');select.name='selected_option';select.append(option('','Free-form answer'));for(const value of escalation.options)select.append(option(value,value));choiceLabel.append(select);form.append(choiceLabel)}const answerLabel=document.createElement('label');answerLabel.textContent=escalation.options?.length?'Answer (optional when a choice is selected)':'Answer';const textarea=document.createElement('textarea');textarea.name='answer';textarea.maxLength=4000;textarea.rows=2;const choice=form.elements.selected_option;textarea.required=!choice?.value;choice?.addEventListener('change',()=>{textarea.required=!choice.value});answerLabel.append(textarea);const submit=document.createElement('button');submit.className='primary';submit.type='submit';submit.textContent=escalation.blocking?'Answer and queue task':'Record answer';form.append(answerLabel,submit);form.addEventListener('submit',event=>answerEscalation(task,escalation,event));panel.append(form)}container.append(panel)}}
