function recoveryRun(task){
  if(!['stale','waiting','blocked'].includes(task.status))return null;
  const runs=task.runs||[];
  if(runs.some(run=>!run.ended_at&&Date.parse(run.lease_expires_at)>=Date.now()))return null;
  return task.status==='stale'?runs.find(run=>run.status==='stale'&&run.ended_at)||null:runs[0]||null;
}
function availableControl(task){const recovery=recoveryRun(task);if(recovery)return {run:recovery,kinds:[task.status==='stale'?'retry':'resume'],review:true};const active=task.runs?.find(run=>run.status==='active'&&!run.ended_at);if(active&&task.status==='active')return {run:active,kinds:['pause','cancel']};const ended=task.runs?.find(run=>run.ended_at);if(ended&&task.status==='cancelled')return {run:ended,kinds:['retry']};return null}
function recoveryLabel(task){return task.visibility==='agent'?'Release to queue':'Review & requeue'}
async function requeueTask(task,run,reviewNote){
  const data=await api(`/api/v1/tasks/${task.id}/review-requeue`,{method:'POST',body:JSON.stringify({expected_version:task.version,target_run_id:run.id,review_note:reviewNote})});
  const items=state.controls.get(task.id)||[];
  state.controls.set(task.id,[data.control,...items.filter(item=>item.id!==data.control.id)]);
  replaceTask(data.task);
  render();
}
async function releaseTask(task,button){
  const run=recoveryRun(task);
  if(!run||!canRecover(task))return;
  const message=task.visibility==='agent'?'Remove the current assignment and return this task to agent pickup. Another agent may start it immediately. The checklist and run history are preserved.':'Return this task to the queue for a fresh run. Its assignment, visibility, checklist and run history are preserved.';
  const note=await appDialog({title:recoveryLabel(task),message,input:{label:'Review note',maxLength:1000},confirmLabel:recoveryLabel(task)});
  if(!note)return;
  button.disabled=true;
  try{await requeueTask(task,run,note)}catch(error){button.disabled=false;await notify(error.message);if(error.message.includes('conflict'))await load()}
}
function renderControls(task,card){const list=$('.control-list',card),form=$('.control-form',card),items=state.controls.get(task.id)||[];list.replaceChildren();for(const control of items){const row=document.createElement('article');row.className='control-request';const header=document.createElement('div');header.className='control-request-header';const title=document.createElement('strong');const run=task.runs?.find(candidate=>candidate.id===control.target_run_id);title.textContent=`${control.kind} · ${run?.callsign||control.target_agent}`;const status=document.createElement('span');status.className='control-status';status.textContent=control.status;header.append(title,status);row.append(header);if(control.reason){const reason=document.createElement('p');reason.textContent=`Request: ${control.reason}`;row.append(reason)}if(control.outcome_note){const outcome=document.createElement('p');outcome.textContent=`Outcome: ${control.outcome_note}`;row.append(outcome)}list.append(row)}const available=availableControl(task);if(available&&task.status!=='stale'){const open=new Set(items.filter(item=>item.target_run_id===available.run.id&&['requested','acknowledged','accepted'].includes(item.status)).map(item=>item.kind));available.kinds=available.kinds.filter(kind=>!open.has(kind))}const recovery=Boolean(available?.review)||task.status==='stale'&&available?.kinds.includes('retry');form.hidden=!(recovery?canRecover(task):canWriteTasks())||!available||!available.kinds.length;const toggle=$('.control-toggle',card);toggle.hidden=form.hidden;if(recovery)toggle.open=true;$('summary',toggle).textContent=recovery?'Review and requeue':'Pause or stop the agent';if(form.hidden)return;form.elements.target_run_id.value=available.run.id;const kind=form.elements.kind,selected=kind.value;kind.replaceChildren(...available.kinds.map(value=>option(value,value[0].toUpperCase()+value.slice(1))));if(available.kinds.includes(selected))kind.value=selected;$('.control-kind-label',form).textContent=recovery?'Recovery':'Request';$('.control-reason-label',form).textContent=recovery?'Review note':'Reason';form.elements.reason.required=recovery;form.elements.reason.placeholder=recovery?'Required summary of your review':'Optional context for the controller';$('.request-control',form).textContent=recovery?recoveryLabel(task):'Send request';$('.requeue-help',form).hidden=!recovery}
async function submitControl(task,card,event){event.preventDefault();const form=event.currentTarget,button=$('.request-control',form),kind=form.elements.kind.value,reviewing=Boolean(availableControl(task)?.review)||task.status==='stale'&&kind==='retry';button.disabled=true;try{const path=reviewing?`/api/v1/tasks/${task.id}/review-requeue`:`/api/v1/tasks/${task.id}/controls`,body=reviewing?{expected_version:task.version,target_run_id:form.elements.target_run_id.value,review_note:form.elements.reason.value.trim()}:{expected_version:task.version,target_run_id:form.elements.target_run_id.value,kind,reason:form.elements.reason.value.trim()};const data=await api(path,{method:'POST',body:JSON.stringify(body)}),items=state.controls.get(task.id)||[];state.controls.set(task.id,[data.control,...items.filter(item=>item.id!==data.control.id)]);form.elements.reason.value='';if(reviewing){replaceTask(data.task);render()}else renderControls(task,card)}catch(error){$('.conversation-status',card).textContent=error.message;if(error.message.includes('conflict'))load()}finally{button.disabled=false}}
function setMessageContext(form,field,message){form.elements.reply_to_id.value='';form.elements.supersedes_id.value='';form.elements[field].value=message.id;const context=$('.message-context',form);context.hidden=false;$('span',context).textContent=field==='supersedes_id'?`Editing message from ${messageAuthor(state.tasks.find(task=>task.id===message.task_id)||{},message)}`:`Replying to ${messageAuthor(state.tasks.find(task=>task.id===message.task_id)||{},message)}`;if(field==='supersedes_id'){form.elements.kind.value=message.kind;form.elements.body.value=message.body;form.elements.requires_ack.checked=message.requires_ack;form.elements.target_run_id.value=message.target_run_id||''}form.elements.body.focus()}
function clearMessageContext(form){form.elements.reply_to_id.value='';form.elements.supersedes_id.value='';const context=$('.message-context',form);context.hidden=true;$('span',context).textContent=''}
function timelineEntries(task){const shown=new Set((state.escalations.get(task.id)||[]).flatMap(escalation=>[escalation.question_message_id,escalation.answer_message_id]));const entries=(state.messages.get(task.id)||[]).filter(message=>!shown.has(message.id)).map(message=>({at:Date.parse(message.created_at),message}));for(const discussion of state.discussions.get(task.id)||[])for(const message of discussion.messages||[])entries.push({at:Date.parse(message.created_at),live:message});return entries.sort((left,right)=>left.at-right.at)}
function liveMessageRow(message){const row=document.createElement('li');row.className='message live-message';row.dataset.role=message.role;const header=document.createElement('div');header.className='message-header';const author=document.createElement('strong');author.textContent=message.role==='agent'?'Agent':(message.author===state.principal?'You':message.author);const kind=document.createElement('span');kind.className='message-kind';kind.textContent='live chat';const time=document.createElement('time');time.dateTime=message.created_at;time.textContent=relativeTime(message.created_at);header.append(author,kind,time);const body=document.createElement('p');linkedText(body,message.body);row.append(header,body);return row}
function renderConversation(task,card){const messages=state.messages.get(task.id);const status=$('.conversation-status',card),list=$('.message-list',card),count=$('.message-count',card),form=$('.message-form',card);list.replaceChildren();const entries=timelineEntries(task);count.textContent=entries.length?`(${entries.length})`:'';if(!messages){status.textContent='Open to load messages.'}else if(!entries.length){status.textContent='No messages yet.'}else{status.textContent='';const superseded=new Set(messages.map(message=>message.supersedes_id).filter(Boolean));for(const entry of entries){if(entry.live){list.append(liveMessageRow(entry.live));continue}const message=entry.message;const row=document.createElement('li');row.className='message';row.dataset.kind=message.kind;if(superseded.has(message.id))row.classList.add('superseded');const header=document.createElement('div');header.className='message-header';const author=document.createElement('strong');author.textContent=messageAuthor(task,message);const kind=document.createElement('span');kind.className='message-kind';kind.textContent=message.kind;const time=document.createElement('time');time.dateTime=message.created_at;time.textContent=relativeTime(message.created_at);header.append(author,kind,time);const body=document.createElement('p');linkedText(body,message.body);const footer=document.createElement('div');footer.className='message-footer';const receipt=document.createElement('span');receipt.textContent=receiptLabel(task,message);footer.append(receipt);if(canWriteTasks()){const reply=document.createElement('button');reply.className='text-button';reply.type='button';reply.textContent='Reply';reply.addEventListener('click',()=>{form.elements.channel.value='queued';setMessageContext(form,'reply_to_id',message);updateComposer(task,card)});footer.append(reply);if(message.author===state.identity&&!superseded.has(message.id)){const edit=document.createElement('button');edit.className='text-button';edit.type='button';edit.textContent='Edit';edit.addEventListener('click',()=>{form.elements.channel.value='queued';setMessageContext(form,'supersedes_id',message);updateComposer(task,card)});footer.append(edit)}}row.append(header,body,footer);list.append(row)}}restoreMessageScroll(task,card);renderEscalations(task,card);renderControls(task,card);form.hidden=!canWriteTasks();if(!canWriteTasks())return;updateComposer(task,card);const target=form.elements.target_run_id,targetValue=target.value;target.replaceChildren(option('','Task context'));for(const run of task.runs?.filter(run=>run.status==='active'&&!run.ended_at)||[])target.append(option(run.id,run.callsign));target.value=[...target.options].some(item=>item.value===targetValue)?targetValue:''}
function restoreMessageScroll(task,card){const list=$('.message-list',card),apply=()=>{const saved=state.messageScroll.get(task.id);list.scrollTop=saved==null?list.scrollHeight:saved};if(list.isConnected)apply();else queueMicrotask(apply)}
function updateComposer(task,card){const form=$('.message-form',card),item=currentDiscussion(task),liveOpen=Boolean(item&&item.status!=='ended'),canLive=Boolean(task.discussable||liveOpen);let channel=form.elements.channel.value;if(!canLive)channel='queued';else if(!channel)channel='live';form.elements.channel.value=channel;const live=channel==='live';$('.message-mode',form).hidden=!canLive;$('.message-options',form).hidden=live;form.elements.body.placeholder=live?'Ask the agent about this task':'Leave a note or direction; the agent reads it at its next check-in';const liveStatus=$('.live-status',form);liveStatus.hidden=!live;liveStatus.textContent=discussionState(item);$('.end-discussion',form).hidden=!liveOpen}
function currentTaskCard(task){const card=$('#taskInspector .task-card');return card?.dataset.taskId===task.id?card:null}
function latestTask(task){return state.tasks.find(item=>item.id===task.id)||task}
async function loadConversation(task,card){const status=$('.conversation-status',card);if(!state.messages.has(task.id))status.textContent='Loading messages…';try{const [messageData,escalationData,controlData,discussionData]=await Promise.all([api(`/api/v1/tasks/${task.id}/messages?limit=200`),api(`/api/v1/tasks/${task.id}/escalations`),api(`/api/v1/tasks/${task.id}/controls`),api(`/api/v1/tasks/${task.id}/discussions`)]);state.messages.set(task.id,messageData.messages||[]);state.escalations.set(task.id,escalationData.escalations||[]);state.controls.set(task.id,controlData.controls||[]);state.discussions.set(task.id,discussionData.discussions||[]);const current=currentTaskCard(task);if(current){rememberInspector();renderConversation(latestTask(task),current);restoreInspector(current,state.detailDrafts.get(task.id));updateComposer(latestTask(task),current)}}catch(error){status.textContent=error.message}}
async function submitMessage(task,card,event){event.preventDefault();const form=event.currentTarget,button=$('.send-message',form),text=form.elements.body.value.trim();if(!text)return;button.disabled=true;try{if(form.elements.channel.value==='live'){const item=currentDiscussion(task);if(item&&item.status!=='ended')await api(`/api/v1/discussions/${item.id}/messages`,{method:'POST',body:JSON.stringify({body:text})});else await api(`/api/v1/tasks/${task.id}/discussions`,{method:'POST',body:JSON.stringify({message:text})})}else{const body={kind:form.elements.kind.value,body:text,target_run_id:form.elements.target_run_id.value,requires_ack:form.elements.requires_ack.checked,reply_to_id:form.elements.reply_to_id.value,supersedes_id:form.elements.supersedes_id.value};await api(`/api/v1/tasks/${task.id}/messages`,{method:'POST',body:JSON.stringify(body)});clearMessageContext(form)}form.elements.body.value='';const current=currentTaskCard(task),composer=current&&$('.message-form',current);if(composer&&composer!==form&&composer.elements.body.value.trim()===text){composer.elements.body.value='';clearMessageContext(composer)}state.messageScroll.delete(task.id);await loadConversation(task,card)}catch(error){$('.conversation-status',card).textContent=error.message}finally{button.disabled=false}}
function currentDiscussion(task){return (state.discussions.get(task.id)||[])[0]}
function discussionState(item){if(!item||item.status==='ended')return 'Live chat is read-only: the agent can answer questions, but nothing said here approves or changes anything.';if(item.status==='requested')return 'Waiting for the agent to join…';return item.agent_status==='thinking'?'Agent is thinking…':'Agent is connected.'}
async function endDiscussion(task,card){const item=currentDiscussion(task);if(!item)return;try{await api(`/api/v1/discussions/${item.id}/end`,{method:'POST',body:'{}'});await loadConversation(task,card)}catch(error){$('.conversation-status',card).textContent=error.message}}
function setupConversation(task,card){const details=$('.conversation',card),form=$('.message-form',card),kind=form.elements.kind,list=$('.message-list',card);details.open=state.openConversations.has(task.id);details.addEventListener('toggle',()=>{if(details.open){state.openConversations.add(task.id);restoreMessageScroll(task,card);if(!state.messages.has(task.id))loadConversation(task,card)}else state.openConversations.delete(task.id)});list.addEventListener('scroll',()=>{if(list.scrollHeight)state.messageScroll.set(task.id,list.scrollHeight-list.scrollTop-list.clientHeight<24?null:list.scrollTop)});for(const radio of form.elements.channel)radio.addEventListener('change',()=>{if(radio.value==='live')clearMessageContext(form);updateComposer(task,card)});kind.addEventListener('change',()=>{const instruction=kind.value==='instruction';if(instruction)form.elements.requires_ack.checked=true;form.elements.requires_ack.disabled=instruction});$('.clear-message-context',form).addEventListener('click',()=>clearMessageContext(form));$('.end-discussion',form).addEventListener('click',()=>endDiscussion(task,card));form.addEventListener('submit',event=>submitMessage(task,card,event));$('.control-form',card).addEventListener('submit',event=>submitControl(task,card,event));renderConversation(task,card);if(details.open&&!state.messages.has(task.id))queueMicrotask(()=>loadConversation(task,card))}
function safeReferenceURL(value){try{const parsed=new URL(value);return parsed.protocol==='https:'&&!parsed.username&&!parsed.password?parsed.href:''}catch{return ''}}
function renderCompletion(task,card,data){const list=$('.completion-list',card),form=$('.completion-form',card);list.replaceChildren();for(const requirement of data?.completion||[]){const panel=document.createElement('article');panel.className='completion-requirement';panel.dataset.status=requirement.status;const title=document.createElement('strong');title.textContent=requirement.label;const status=document.createElement('span');status.textContent=requirement.required?requirement.status:`optional · ${requirement.status}`;panel.append(title,status);if(requirement.evidence?.length){const evidence=document.createElement('ul');evidence.className='completion-evidence';for(const item of requirement.evidence){const row=document.createElement('li');row.textContent=`${item.status}: ${item.note||item.reference_id||'Evidence'}`;evidence.append(row)}panel.append(evidence)}if(canWriteTasks()&&requirement.status==='pending'){const actions=document.createElement('div');actions.className='completion-actions';const submitted=requirement.evidence?.find(item=>item.status==='submitted');if(requirement.kind==='human_approval'||submitted){const verify=document.createElement('button');verify.type='button';verify.className='secondary';verify.textContent='Verify';verify.addEventListener('click',()=>reviewCompletion(task,requirement,'satisfied',submitted?.id||''));actions.append(verify)}const waive=document.createElement('button');waive.type='button';waive.className='text-button';waive.textContent='Waive';waive.addEventListener('click',async()=>{const reason=await appDialog({title:'Waive completion gate',message:requirement.label,input:{label:'Why is this gate waived?',maxLength:1000},confirmLabel:'Waive gate'});if(reason)reviewCompletion(task,requirement,'waived','',reason)});actions.append(waive);panel.append(actions)}list.append(panel)}form.hidden=!canWriteTasks()||['done','cancelled'].includes(task.status)}
async function submitCompletion(task,card,event){event.preventDefault();const form=event.currentTarget,button=$('.add-completion',form);button.disabled=true;try{await api(`/api/v1/tasks/${task.id}/completion`,{method:'POST',body:JSON.stringify({expected_version:task.version,kind:form.elements.kind.value,label:form.elements.label.value.trim(),required:form.elements.required.checked})});state.deliveries.delete(task.id);await refreshTasks()}catch(error){$('.delivery-status',card).textContent=error.message;button.disabled=false}}
async function reviewCompletion(task,requirement,status,evidenceID='',note=''){try{await api(`/api/v1/tasks/${task.id}/completion/${requirement.id}`,{method:'PATCH',body:JSON.stringify({expected_version:task.version,status,evidence_id:evidenceID,note})});state.deliveries.delete(task.id);await refreshTasks()}catch(error){notify(error.message)}}
function renderDelivery(task,card){const data=state.deliveries.get(task.id),status=$('.delivery-status',card),milestones=$('.milestone-list',card),references=$('.reference-list',card),handoffs=$('.handoff-list',card),count=$('.reference-count',card),form=$('.reference-form',card);milestones.replaceChildren();references.replaceChildren();handoffs.replaceChildren();const total=data?data.references.length+data.handoffs.length+data.completion.length:task.link_count||0;count.textContent=total?`(${total})`:'';if(!data){status.textContent='Loading links…'}else{status.textContent=total?'':'Nothing linked yet.';for(const milestone of data.milestones){const row=document.createElement('li');row.className='milestone';const label=document.createElement('span');label.textContent=milestone.label;const time=document.createElement('time');time.dateTime=milestone.reached_at;time.textContent=relativeTime(milestone.reached_at);row.append(label,time);milestones.append(row)}for(const handoff of data.handoffs){const panel=document.createElement('article');panel.className='handoff';const title=document.createElement('strong');title.textContent=`${handoff.kind} handoff`;const meta=document.createElement('span');meta.textContent=`${relativeTime(handoff.created_at)} · ${handoff.created_by}`;panel.append(title,meta);for(const [label,value] of [['Last step',handoff.last_completed_step],['Workspace',handoff.worktree],['Branch',handoff.branch],['Blocker',handoff.blocker],['Next',handoff.next_action],['Commits',handoff.commits?.join(', ')],['Pull requests',handoff.pull_requests?.join(', ')],['Validation',handoff.validation?.join(' · ')],['Review findings',handoff.review_findings?.join(' · ')]])if(value){const row=document.createElement('p');row.textContent=`${label}: ${value}`;panel.append(row)}handoffs.append(panel)}for(const reference of data.references){const row=document.createElement('li');row.className='reference';const kind=document.createElement('span');kind.className='reference-kind';kind.textContent=reference.kind.replaceAll('_',' ');const main=document.createElement('div');const href=safeReferenceURL(reference.url);if(href){const link=document.createElement('a');link.href=href;link.target='_blank';link.rel='noopener noreferrer';link.textContent=reference.label;main.append(link)}else{const label=document.createElement('strong');label.textContent=reference.label;main.append(label)}if(reference.locator){const locator=document.createElement('code');locator.textContent=reference.locator;main.append(document.createElement('br'),locator)}const provenance=document.createElement('span');provenance.className='reference-provenance';provenance.textContent=reference.provenance;row.append(kind,main,provenance);references.append(row)}}renderCompletion(task,card,data);$('.link-add',card).hidden=!canWriteTasks()||!state.addingLinks.has(task.id)}
async function loadDelivery(task,card){const status=$('.delivery-status',card);if(!state.deliveries.has(task.id))status.textContent='Loading links…';try{const data=await api(`/api/v1/tasks/${task.id}/delivery`);state.deliveries.set(task.id,{references:data.references||[],milestones:data.milestones||[],handoffs:data.handoffs||[],completion:data.completion||[]});const current=currentTaskCard(task);if(current)renderDelivery(latestTask(task),current)}catch(error){status.textContent=error.message}}
