function renderTaskContext(task,card){const context=$('.task-context',card);context.hidden=!task.summary;if(task.summary)$('p',context).textContent=task.summary}
function setupDelivery(task,card){renderTaskContext(task,card);const details=$('.delivery',card),form=$('.reference-form',card),add=$('.add-link',card);details.hidden=!task.link_count&&!state.addingLinks.has(task.id);details.open=state.openDeliveries.has(task.id)||state.addingLinks.has(task.id);details.addEventListener('toggle',()=>{if(details.open){state.openDeliveries.add(task.id);if(!state.deliveries.has(task.id))loadDelivery(task,card)}else state.openDeliveries.delete(task.id)});add.hidden=!canWriteTasks();add.addEventListener('click',()=>{state.addingLinks.add(task.id);setDetailTab('delivery');details.hidden=false;details.open=true;$('.link-add',card).hidden=false;form.elements.label.focus()});form.addEventListener('submit',event=>submitReference(task,card,event));$('.completion-form',card).addEventListener('submit',event=>submitCompletion(task,card,event));renderDelivery(task,card);if(details.open&&!state.deliveries.has(task.id))queueMicrotask(()=>loadDelivery(task,card))}
function renderTask(task){const card=$('#taskTemplate').content.firstElementChild.cloneNode(true);card.dataset.taskId=task.id;card.dataset.status=task.status;card.dataset.priority=task.priority;$('.task-title',card).textContent=task.title;$('.task-progress',card).textContent=progress(task);$('.task-note',card).textContent=task.current_note||task.summary||statusLabel(task.status);const agentChip=$('.agent-chip',card);$('time',card).textContent=relativeTime(task.updated_at);$('time',card).dateTime=task.updated_at;$('.repository',card).textContent=task.project||task.repository||'No project';const latest=task.runs?.find(run=>run.status==='active')||task.runs?.[0];if(latest&&latest.agent===task.owner)renderAgentChip(agentChip,latest);else agentChip.textContent=task.owner||'Unassigned';$('.run-state',card).textContent=latest?`${statusLabel(latest.status)} · ${latest.callsign}`:task.visibility==='agent'&&task.status==='queued'?(task.ready?'Available for pickup':deferred(task)?`Starts ${deferLabel(task.defer_until)}`:'Waiting on dependencies'):task.status==='queued'&&task.owner?`Queued for ${task.owner}`:statusLabel(task.status);const attention=$('.attention-note',card);if(task.blocker||task.waiting_for||task.status==='stale'){attention.hidden=false;statusNote(attention,task.blocker||task.waiting_for||'The agent stopped checking in.')}const meta=$('.task-meta',card);const laneLabels={private:'Private',team:'Team',agent:'Agent pickup'};const labels=[laneLabels[task.visibility]||'Team'];if(!state.taskType)labels.push(task.type==='work'?'Work':'Personal');if(task.priority&&task.priority!=='normal')labels.push(task.priority);if(task.due_date)labels.push(task.due_date<localDate()?`Overdue · ${task.due_date}`:`Due ${task.due_date}`);if(task.defer_until)labels.push(`${task.visibility==='agent'&&deferred(task)?'Starts':'Deferred to'} ${deferLabel(task.defer_until)}`);if(task.schedule_id)labels.push('Scheduled run');if(task.recurrence)labels.push(`↻ ${task.recurrence}`);if(task.repository&&task.project)labels.push(task.repository);if(labels.length){meta.hidden=false;for(const label of labels){const chip=document.createElement('span');chip.textContent=label;meta.append(chip)}}$('.task-assignment',card).textContent=task.owner?`Assigned to: ${task.owner}`:'Unassigned';renderDependencies(task,card);renderDuplicates(task,card);renderRequirements(task,card);const list=$('.checklist',card);for(const item of task.items){const row=document.createElement('li');row.dataset.status=item.status;row.dataset.itemId=item.id;const itemNote=item.note?`<span class="item-note"></span>`:'';row.innerHTML=`<button class="item-state" type="button" aria-label="Mark step complete"></button><span class="item-label"></span>${itemNote}`;$('.item-label',row).textContent=item.label;if(item.note)$('.item-note',row).textContent=item.note;const stateButton=$('.item-state',row);stateButton.setAttribute('aria-label',`Mark “${item.label}” complete`);if(!canWriteTasks()||task.status==='queued'||['done','skipped'].includes(item.status)||['done','cancelled'].includes(task.status)){stateButton.disabled=true}else{stateButton.addEventListener('click',()=>completeItem(task,item,stateButton))}list.append(row)}$('.empty-checklist',card).hidden=Boolean(task.items.length);renderRunDetails(task,card);setupDelivery(task,card);setupConversation(task,card);const actions=$('.task-actions',card);if(canWriteTasks()&&task.status==='queued'&&task.visibility!=='agent'){actions.hidden=false;$('.finish-self',actions).hidden=true;$('.start-self',actions).addEventListener('click',event=>startMyself(task,event.currentTarget));const assign=$('.assign-form',actions);assign.hidden=task.visibility==='private';if(!assign.hidden)assign.addEventListener('submit',event=>assignTask(task,event))}else if(canWriteTasks()&&task.status==='active'&&!task.items.length&&!task.runs?.some(run=>run.status==='active')){actions.hidden=false;$('.start-self',actions).hidden=true;$('.assign-form',actions).hidden=true;$('.finish-self',actions).addEventListener('click',event=>finishTask(task,event.currentTarget))}if(task.cancel_requested&&task.runs?.some(run=>run.status==='active'&&!run.ended_at)){const cancel=$('.cancel-task',card);cancel.disabled=true;cancel.textContent='Cancel requested…'}const release=$('.release-task',card);release.hidden=!canRecover(task)||!recoveryRun(task);release.textContent=recoveryLabel(task);release.addEventListener('click',()=>releaseTask(task,release));const edit=$('.edit-task',card);edit.hidden=!canWriteTasks();if(canWriteTasks())edit.addEventListener('click',()=>openEditTask(task));const terminal=['done','cancelled'].includes(task.status);const manualOrder=state.sort==='manual'&&state.filter!=='work';$('.move-up',card).hidden=terminal||!canWriteTasks()||!manualOrder;$('.move-down',card).hidden=terminal||!canWriteTasks()||!manualOrder;$('.review-task',card).hidden=terminal||!canWriteTasks();if(!terminal&&canWriteTasks()){$('.move-up',card).addEventListener('click',event=>moveTask(task,'up',event.currentTarget));$('.move-down',card).addEventListener('click',event=>moveTask(task,'down',event.currentTarget));$('.review-task',card).addEventListener('click',event=>mutateTask(task,{reviewed:true},event.currentTarget))}return card}
async function renameAgentRun(task,run,button){const callsign=await appDialog({title:'Rename agent',input:{label:'Friendly agent name',value:run.callsign,maxLength:100},confirmLabel:'Rename'});if(!callsign||callsign.trim()===run.callsign)return;button.disabled=true;try{const data=await api(`/api/v1/tasks/${task.id}/runs/${run.id}`,{method:'PATCH',body:JSON.stringify({expected_version:task.version,callsign:callsign.trim()})});replaceTask(data.task);render()}catch(error){button.disabled=false;if(error.message.includes('conflict'))load();else notify(error.message)}}
async function completeItem(task,item,button){button.disabled=true;const remaining=task.items.filter(candidate=>candidate.id!==item.id&&!['done','skipped'].includes(candidate.status));const next=remaining[0];const body={expected_version:task.version,complete_item_ids:[item.id]};if(next)body.current_item_id=next.id;else body.status='done';try{const data=await api(`/api/v1/tasks/${task.id}`,{method:'PATCH',body:JSON.stringify(body)});replaceTask(data.task);render()}catch(error){button.disabled=false;if(error.message.includes('conflict'))load();else notify(error.message)}}
async function mutateTask(task,body,button){if(button)button.disabled=true;try{const data=await api(`/api/v1/tasks/${task.id}`,{method:'PATCH',body:JSON.stringify({expected_version:task.version,...body})});replaceTask(data.task);render()}catch(error){if(button)button.disabled=false;if(error.message.includes('conflict'))load();else notify(error.message)}}
async function cancelTaskFromCard(task,button){const activeRun=task.runs?.find(run=>run.status==='active'&&!run.ended_at);const prompt=activeRun?`Request cancellation of “${task.title}”? The agent will acknowledge and stop at a safe point.`:`Cancel “${task.title}”?`;if(!await appDialog({title:activeRun?'Request cancellation':'Cancel task',message:prompt,confirmLabel:activeRun?'Request cancellation':'Cancel task',cancelLabel:'Keep task',danger:true}))return;button.disabled=true;try{if(activeRun){const data=await api(`/api/v1/tasks/${task.id}/controls`,{method:'POST',body:JSON.stringify({expected_version:task.version,target_run_id:activeRun.id,kind:'cancel',reason:'Cancellation requested from the task card.'})});const items=state.controls.get(task.id)||[];state.controls.set(task.id,[data.control,...items]);task.cancel_requested=true;button.textContent='Cancel requested…'}else{const data=await api(`/api/v1/tasks/${task.id}`,{method:'PATCH',body:JSON.stringify({expected_version:task.version,status:'cancelled',current_note:'Cancelled by user.'})});replaceTask(data.task);render()}}catch(error){button.disabled=false;if(error.message.includes('conflict'))load();else notify(error.message)}}
$('#taskInspector').addEventListener('click',event=>{const button=event.target.closest('.cancel-task');if(!button)return;const task=state.tasks.find(candidate=>candidate.id===button.closest('.task-card')?.dataset.taskId);if(task)cancelTaskFromCard(task,button)});
function startMyself(task,button){return mutateTask(task,{status:'active',owner:state.identity||'Me'},button)}
function finishTask(task,button){return mutateTask(task,{status:'done'},button)}
function assignTask(task,event){event.preventDefault();const input=$('input',event.currentTarget);const owner=input.value.trim();if(owner)mutateTask(task,{owner},$('button',event.currentTarget))}
async function moveTask(task,direction,button){button.disabled=true;try{await api(`/api/v1/tasks/${task.id}/move`,{method:'POST',body:JSON.stringify({expected_version:task.version,direction})});await refreshTasks()}catch(error){button.disabled=false;if(error.message.includes('conflict'))load();else notify(error.message)}}
function statusLabel(value){return ({queued:'Queued',active:'Working',waiting:'Waiting',blocked:'Blocked',stale:'Stale',done:'Done',cancelled:'Cancelled'})[value]||value}

async function fetchAllTasks(query=''){const tasks=[],seen=new Set();let cursor='';for(let page=0;page<50;page++){const params=['limit=200'];if(query)params.push(query);if(cursor)params.push(`cursor=${encodeURIComponent(cursor)}`);const data=await api(`/api/v1/tasks?${params.join('&')}`);tasks.push(...(data.tasks||[]));cursor=data.next_cursor||'';if(!cursor||seen.has(cursor))break;seen.add(cursor)}return tasks}
async function refreshTasks(){const [tasks,templates]=await Promise.all([fetchAllTasks(),api('/api/v1/templates')]);state.tasks=tasks;state.templates=templates.templates||[];renderTemplateOptions();render();notificationSweep();scheduleDeferRefresh()}
// Milliseconds until a loaded task's deferral ends, so its server-computed readiness is reloaded then; null when none is pending. A deferral the server still reports after its local start (its review timezone differs) is rechecked each minute.
function nextDeferRefresh(tasks,now=Date.now()){let next=null;for(const task of tasks){if(!task.deferred||!task.defer_until)continue;const start=Date.parse(task.defer_until.includes('T')?task.defer_until:`${task.defer_until}T00:00`);const wait=Number.isFinite(start)&&start>now?start-now+1000:60000;next=next===null?wait:Math.min(next,wait)}return next===null?null:Math.min(next,2147483647)}
let deferRefreshTimer;function scheduleDeferRefresh(){clearTimeout(deferRefreshTimer);const wait=nextDeferRefresh(state.tasks);if(wait!==null)deferRefreshTimer=setTimeout(()=>refreshTasks().catch(()=>{}),wait)}
function stopEventStream(){const source=state.eventSource;state.eventSource=null;source?.close();clearTimeout(state.eventWatchdog);state.eventWatchdog=null;state.lastEventAt=0}
function cancelReconnect(){clearTimeout(state.reconnectTimer);state.reconnectTimer=null}
function disconnectEvents(){stopEventStream();cancelReconnect()}
function requireSignIn(){state.authenticated=false;state.tasks=[];state.selectedTask=null;state.detailDrafts.clear();state.messages.clear();state.escalations.clear();state.controls.clear();state.deliveries.clear();state.discussions.clear();render();disconnectEvents();$('#logoutButton').hidden=true;setConnection('offline','Sign in');if(!loginDialog.open)loginDialog.showModal()}
function scheduleReconnect(delay=eventReconnectDelay){if(!state.authenticated||state.reconnectTimer)return;stopEventStream();setConnection('offline','Reconnecting');state.reconnectTimer=setTimeout(()=>{state.reconnectTimer=null;load()},delay)}
function noteEvent(source){if(source!==state.eventSource)return;state.lastEventAt=Date.now();clearTimeout(state.eventWatchdog);state.eventWatchdog=setTimeout(()=>{if(source===state.eventSource)scheduleReconnect()},eventStaleAfter)}
async function load(){cancelReconnect();try{await refreshTasks();const linked=new URLSearchParams(location.search).get('task');if(linked&&!state.linkedTaskOpened&&state.tasks.some(task=>task.id===linked)){state.linkedTaskOpened=true;selectTask(linked,true)}state.authenticated=true;$('#logoutButton').hidden=false;setConnection('offline','Connecting');connectEvents()}catch(error){if(error.message==='AUTH'){requireSignIn()}else{setConnection('offline','Offline');if(!state.tasks.length)board.innerHTML='<div class="empty"><strong>Taskboard is unavailable</strong><span>We’ll retry automatically.</span></div>';scheduleReconnect(5000)}}}
function connectEvents(){stopEventStream();const source=new EventSource('/api/v1/events');state.eventSource=source;source.addEventListener('ready',async()=>{noteEvent(source);setConnection('live','Live');try{await refreshTasks()}catch(error){if(error.message==='AUTH')requireSignIn();else scheduleReconnect()}});source.addEventListener('ping',()=>noteEvent(source));source.addEventListener('task',async event=>{noteEvent(source);const change=JSON.parse(event.data);const previous=state.tasks.find(task=>task.id===change.task_id);try{if(change.payload?.reload){await refreshTasks();return}const open=state.messages.has(change.task_id),deliveryOpen=state.deliveries.has(change.task_id);const discussionOpen=open;const [data,messageData,escalationData,controlData,deliveryData,discussionData]=await Promise.all([api(`/api/v1/tasks/${change.task_id}`),open?api(`/api/v1/tasks/${change.task_id}/messages?limit=200`):Promise.resolve(null),open?api(`/api/v1/tasks/${change.task_id}/escalations`):Promise.resolve(null),open?api(`/api/v1/tasks/${change.task_id}/controls`):Promise.resolve(null),deliveryOpen?api(`/api/v1/tasks/${change.task_id}/delivery`):Promise.resolve(null),discussionOpen?api(`/api/v1/tasks/${change.task_id}/discussions`):Promise.resolve(null)]);if(messageData)state.messages.set(change.task_id,messageData.messages||[]);if(escalationData)state.escalations.set(change.task_id,escalationData.escalations||[]);if(controlData)state.controls.set(change.task_id,controlData.controls||[]);if(discussionData)state.discussions.set(change.task_id,discussionData.discussions||[]);if(deliveryData)state.deliveries.set(change.task_id,{references:deliveryData.references||[],milestones:deliveryData.milestones||[],handoffs:deliveryData.handoffs||[],completion:deliveryData.completion||[]});state.tasks=state.tasks.filter(task=>task.id!==change.task_id);state.tasks.unshift(data.task);render();notifyChange(previous,data.task,change)}catch(error){if(error.message==='AUTH')requireSignIn();else if(error.message==='not found')await refreshTasks();else scheduleReconnect()}});source.onerror=()=>{if(source===state.eventSource)scheduleReconnect()}}
function setConnection(status,label){const element=$('#connection');element.dataset.state=status;element.textContent=label}

async function showTaskNotification(task,{id,title,body,urgent=false}){if(window.__TAURI__?.core?.invoke){try{await window.__TAURI__.core.invoke('alert',{payload:{id,title,body,urgent}});return}catch(error){console.warn('Native notification failed',error)}}if('Notification'in window&&'serviceWorker'in navigator&&Notification.permission==='granted'){const registration=await navigator.serviceWorker.ready;registration.showNotification(title,{body,icon:'/icons/icon-192.png',tag:`task-${id}`,data:{url:`/?task=${task.id}`},requireInteraction:urgent})}}
async function notifyChange(previous,task,event){const nonblockingQuestion=event.kind==='task.escalated'&&!event.payload?.blocking;if((state.routineProducers||[]).includes(task.created_by)&&!['high','urgent'].includes(task.priority)&&!nonblockingQuestion)return;if(notificationPreferences().progress===false||!previous||event.actor==='user')return;if(event.kind==='task.escalated'){const question=escalationMessage(task.id,event.payload?.question_message_id)?.body||task.waiting_for||'An agent asked a question.';await showTaskNotification(task,{id:`${task.id}-escalation`,title:`${task.title} · ${event.payload?.blocking?'Decision needed':'Question'}`,body:question,urgent:Boolean(event.payload?.blocking)});return}const completedIDs=Array.isArray(event.payload?.completed_item_ids)?event.payload.completed_item_ids:[];for(const id of completedIDs){const item=task.items.find(candidate=>candidate.id===id);if(item)await showTaskNotification(task,{id:`${task.id}-step-${id}`,title:`${task.title} · ${task.status==='done'?'Done':'Step complete'}`,body:item.label})}const important=['blocked','waiting','stale','done'].includes(task.status);if(!important||(task.status==='done'&&completedIDs.length))return;const body=task.blocker||task.waiting_for||task.current_note||`${progress(task)} checklist items complete`;await showTaskNotification(task,{id:task.id,title:`${task.title} · ${statusLabel(task.status)}`,body,urgent:['blocked','stale'].includes(task.status)})}
async function notificationSweep(){const preferences=notificationPreferences(),today=localDate();if(preferences.reminders!==false){for(const task of openTasks().filter(item=>item.due_date&&item.due_date<=today&&!deferred(item))){const key=`taskboard-reminder-${task.id}-${today}`;if(localStorage.getItem(key))continue;localStorage.setItem(key,'sent');await showTaskNotification(task,{id:`${task.id}-due-${today}`,title:`${task.title} · ${task.due_date<today?'Overdue':'Due today'}`,body:task.project||task.summary||'Open Taskboard to review this task.'})}}if(preferences.summaries){const key=`taskboard-summary-${today}`;if(!localStorage.getItem(key)){localStorage.setItem(key,'sent');const due=openTasks().filter(item=>item.due_date&&item.due_date<=today&&!deferred(item)).length,waiting=openTasks().filter(item=>['waiting','blocked','stale'].includes(item.status)).length;if(due||waiting)await showTaskNotification({id:'summary'},{id:`summary-${today}`,title:'Taskboard daily summary',body:`${due} due or overdue · ${waiting} waiting for attention`})}}}

$('#loginForm').addEventListener('submit',async event=>{event.preventDefault();$('#loginError').textContent='';const button=$('#oidcLoginButton');button.disabled=true;try{if(!window.__TAURI__?.core?.invoke){window.location.assign('/api/v1/auth/oidc/start');return}const handoff=Array.from(crypto.getRandomValues(new Uint8Array(32)),value=>value.toString(16).padStart(2,'0')).join('');const verificationCode=`${handoff.slice(0,4)}-${handoff.slice(4,8)}`.toUpperCase();await window.__TAURI__.core.invoke('begin_oidc_login',{handoff});$('#loginCopy').textContent=`Confirm code ${verificationCode} in your browser.`;for(let attempt=0;attempt<600;attempt+=1){await new Promise(resolve=>setTimeout(resolve,1000));const response=await fetch('/api/v1/auth/desktop/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:handoff})});if(response.status===401)continue;if(!response.ok)throw new Error(`Desktop sign-in failed (${response.status})`);loginDialog.close();await initializeSession();return}throw new Error('Desktop sign-in timed out.')}catch(error){$('#loginError').textContent=String(error.message||error);button.disabled=false}});
