// The plaintext token exists only in this field; closing the dialog discards it.
credentialsDialog.addEventListener('close',()=>showCredentialToken(''));
function showCredentialToken(token){const field=$('#credentialTokenValue');field.value=token;$('#credentialToken').hidden=!token;$('#copyCredentialToken').textContent='Copy';if(token){field.focus();field.select()}}
function credentialState(item){return item.revoked_at?'revoked':item.expires_at&&new Date(item.expires_at)<=Date.now()?'expired':'active'}
async function loadCredentials(){const status=$('#credentialsStatus'),list=$('#credentialsList');status.textContent='Loading…';try{const items=(await api('/api/v1/admin/credentials')).credentials||[];list.replaceChildren();status.textContent=items.length?'':'No agent credentials have been issued.';for(const item of items){const row=document.createElement('li'),current=credentialState(item);row.dataset.state=current;const name=document.createElement('strong');name.textContent=item.name;const detail=document.createElement('small');detail.textContent=[item.principal_id,current,`created ${relativeTime(item.created_at)}`,item.expires_at&&current!=='revoked'?`expires ${new Date(item.expires_at).toLocaleDateString()}`:'',item.revoked_at?`revoked ${relativeTime(item.revoked_at)}`:`last used ${item.last_used_at?relativeTime(item.last_used_at):'never'}`].filter(Boolean).join(' · ');row.append(name);if(!item.revoked_at)for(const rotate of [true,false]){const button=document.createElement('button');button.type='button';button.className='text-button';button.textContent=rotate?'Rotate':'Revoke';button.setAttribute('aria-label',`${button.textContent} ${item.name}`);button.addEventListener('click',()=>changeCredential(item,rotate));row.append(button)}row.append(detail);list.append(row)}}catch(error){status.textContent=error.message}}
async function changeCredential(item,rotate){const verb=rotate?'Rotate':'Revoke';if(!await appDialog({title:`${verb} credential`,message:rotate?`Rotate “${item.name}”? Its current token stops working immediately and a replacement is shown once.`:`Revoke “${item.name}” (${item.principal_id})? Agents using it lose access immediately.`,confirmLabel:verb,danger:true}))return;try{const data=await api(`/api/v1/admin/credentials/${encodeURIComponent(item.id)}${rotate?'/rotate':''}`,{method:rotate?'POST':'DELETE'});await loadCredentials();showCredentialToken(data?.token||'')}catch(error){$('#credentialsStatus').textContent=error.message}}
$('#credentialForm').addEventListener('submit',async event=>{event.preventDefault();const expires=$('#credentialExpires').value,payload={name:$('#credentialName').value.trim(),principal_id:$('#credentialPrincipal').value.trim()};if(expires)payload.expires_at=new Date(`${expires}T23:59:59`).toISOString();try{const data=await api('/api/v1/admin/credentials',{method:'POST',body:JSON.stringify(payload)});event.target.reset();await loadCredentials();showCredentialToken(data.token)}catch(error){$('#credentialsStatus').textContent=error.message}});
$('#copyCredentialToken').addEventListener('click',async event=>{const field=$('#credentialTokenValue');try{await navigator.clipboard.writeText(field.value);event.target.textContent='Copied'}catch{field.select();event.target.textContent='Press Ctrl+C'}});
function metricValue(value,kind){if(kind==='rate')return `${(Number(value||0)*100).toFixed(1)}%`;if(kind==='duration'){const seconds=Number(value||0);return seconds>=86400?`${(seconds/86400).toFixed(1)}d`:seconds>=3600?`${(seconds/3600).toFixed(1)}h`:`${Math.round(seconds/60)}m`}if(kind==='cost')return `$${(Number(value||0)/1000000).toFixed(2)}`;return Number(value||0).toLocaleString()}
async function loadAnalytics(){const status=$('#analyticsStatus'),grid=$('#analyticsGrid');status.textContent='Loading…';grid.replaceChildren();try{const data=await api(`/api/v1/analytics?days=${$('#analyticsDays').value}`),item=data.analytics;status.textContent=`${item.window_days}-day aggregate`;for(const [label,key,kind] of [['Tasks created','tasks_created'],['Completion rate','completion_rate','rate'],['Mean queue age','mean_queue_age_seconds','duration'],['Mean execution','mean_execution_seconds','duration'],['Stale-run rate','stale_run_rate','rate'],['Escalation rate','escalation_rate','rate'],['Retries','retries'],['Mean review cycles','mean_review_cycles'],['Input tokens','input_tokens'],['Output tokens','output_tokens'],['Estimated cost','estimated_cost_micros','cost']]){const card=document.createElement('article');const value=document.createElement('strong');value.textContent=metricValue(item[key],kind);const title=document.createElement('span');title.textContent=label;card.append(value,title);grid.append(card)}}catch(error){status.textContent=error.message}}
document.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
function checklistRow(value=''){const row=document.createElement('div');row.className='edit-row';row.innerHTML='<input maxlength="300" placeholder="Describe a concrete step"><button class="remove-item" type="button" aria-label="Remove step">×</button>';$('input',row).value=value;$('.remove-item',row).addEventListener('click',()=>row.remove());return row}
function resetTaskForm(){taskDialog.querySelector('form').reset();$('#taskAssignment').hidden=true;$('#taskID').value='';$('#taskVersion').value='';$('#taskType').value=state.taskType||'personal';$('#taskVisibility').value='private';$('#taskSection').value='General';$('#taskPriority').value='normal';$('#checklistEditor').replaceChildren();$('#checklistEditor').dataset.editable='true';$('#addChecklistItem').disabled=false;$('#taskRequirementsField').hidden=false;$('#taskDialogTitle').textContent='New task';$('#taskSubmitButton').textContent='Create task';$('#taskError').textContent='';$('#taskOptions').open=false;$('.template-options').open=false;$('#taskProject').value=state.project}
function openEditTask(task){resetTaskForm();$('#taskOptions').open=true;$('#taskID').value=task.id;$('#taskVersion').value=task.version;$('#taskTitle').value=task.title;$('#taskType').value=task.type||'personal';$('#taskVisibility').value=task.visibility||'team';$('#taskSection').value=sectionName(task);$('#taskProject').value=task.project||'';$('#taskRepository').value=task.repository||'';$('#taskPriority').value=task.priority||'normal';$('#taskDueDate').value=task.due_date||'';setDeferInputs(task.defer_until||'');$('#taskRecurrence').value=task.recurrence||'';$('#taskSummary').value=task.summary||'';$('#checklistEditor').replaceChildren(...task.items.map(item=>checklistRow(item.label)));const editable=task.status==='queued'&&!task.runs?.length;$('#checklistEditor').dataset.editable=String(editable);$('#addChecklistItem').disabled=!editable;$('#taskRequirementsField').hidden=true;$('#checklistEditor').querySelectorAll('input,button').forEach(element=>element.disabled=!editable);$('#taskDialogTitle').textContent='Edit task';$('#taskSubmitButton').textContent='Save changes';setupTaskAssignment(task);taskDialog.showModal()}
function setupTaskAssignment(task){
  const input=$('#taskOwner');
  $('#taskAssignment').hidden=false;
  input.value=task.owner||'';
  input.dataset.initialOwner=input.value;
  input.dataset.activeRun=String((task.runs||[]).some(run=>run.status==='active'&&!run.ended_at));
  const candidates=new Set([state.identity,task.owner,...state.tasks.flatMap(item=>[item.owner,...(item.runs||[]).map(run=>run.agent)])].filter(Boolean));
  $('#assigneeOptions').replaceChildren(...[...candidates].sort().map(owner=>option(owner,owner===state.identity?'Me':owner)));
  updateAssignmentControls();
}
function updateAssignmentControls(){
  const input=$('#taskOwner'),active=input.dataset.activeRun==='true',pickup=$('#taskVisibility').value==='agent';
  input.disabled=active||pickup;
  $('#unassignTask').disabled=input.disabled||!input.value.trim();
  $('#taskAssignmentHelp').textContent=active?'Stop the current agent run before changing assignment.':pickup?'Agent-pickup tasks are assigned when an agent claims them.':'Choose a person or agent, or leave unassigned. Save changes to apply; task progress and history stay unchanged.';
}
function assignmentPayload(){
  const input=$('#taskOwner'),owner=input.value.trim();
  return $('#taskID').value&&!input.disabled&&owner!==input.dataset.initialOwner?{owner}:{};
}
$('#taskVisibility').addEventListener('change',updateAssignmentControls);
$('#taskOwner').addEventListener('input',updateAssignmentControls);
$('#taskRequirements').addEventListener('input',()=>renderRequirementSuggestions($('#taskRequirementsField .requirement-suggestions'),$('#taskRequirements')));
$('#unassignTask').addEventListener('click',()=>{$('#taskOwner').value='';updateAssignmentControls();$('#taskOwner').focus()});
