async function captureTask(input){return api('/api/v1/tasks/capture',{method:'POST',body:JSON.stringify(input)})}
function quickCapturePayload(title){return {title:title.trim(),visibility:'private',...(state.taskType?{}:{type:'personal'}),section:'General',project:state.project}}
async function quickCapture(event){
  event.preventDefault();
  const input=$('#quickTaskTitle'),button=$('#quickCaptureForm button');
  if(button.disabled)return;
  input.setCustomValidity(input.value.trim()?'':'Enter a task title.');if(!input.reportValidity())return;
  button.disabled=true;input.readOnly=true;$('#quickCaptureError').textContent='';$('#quickCaptureStatus').textContent='';
  try{const data=await captureTask(quickCapturePayload(input.value));state.tasks.unshift(data.task);input.value='';state.search='';$('#taskSearch').value='';setFilter('work',Boolean(state.project));$('#quickCaptureStatus').textContent=`Added “${data.task.title}”.`}
  catch(error){$('#quickCaptureError').textContent=error.message==='AUTH'?'Your session expired. Reload to sign in again.':error.message}
  finally{button.disabled=false;input.readOnly=false;input.focus()}
}

function setFilter(value,keepProject=false){rememberInspector();state.selectedTask=null;state.filter=value;if(!keepProject)state.project='';state.searchAll=false;$('#viewFilter').value=value;document.body.classList.remove('navigation-open');$('#navigationToggle').setAttribute('aria-expanded','false');render()}
