function taskFormPayload(){return {title:$('#taskTitle').value.trim(),...(state.taskType?{}:{type:$('#taskType').value}),visibility:$('#taskVisibility').value,section:$('#taskSection').value.trim(),project:$('#taskProject').value.trim(),repository:$('#taskRepository').value.trim(),priority:$('#taskPriority').value,due_date:$('#taskDueDate').value,defer_until:deferPayload(),recurrence:$('#taskRecurrence').value,summary:$('#taskSummary').value.trim(),checklist:[...$('#checklistEditor').querySelectorAll('input')].map(input=>input.value.trim()).filter(Boolean)}}
