$('#taskForm').addEventListener('submit',async event=>{event.preventDefault();$('#taskError').textContent='';const payload=taskFormPayload(),id=$('#taskID').value;try{let data;if(id){Object.assign(payload,assignmentPayload());if($('#checklistEditor').dataset.editable!=='true')delete payload.checklist;data=await api(`/api/v1/tasks/${id}`,{method:'PATCH',body:JSON.stringify({expected_version:Number($('#taskVersion').value),...payload})});replaceTask(data.task)}else{data=await captureTask({...payload,requirements:requirementList($('#taskRequirements').value)});state.tasks.unshift(data.task);state.search='';$('#taskSearch').value=''}taskDialog.close();setFilter(id?state.filter:'open');selectTask(data.task.id)}catch(error){$('#taskError').textContent=error.message}});
function renderTemplateOptions(){const select=$('#taskTemplateSelect'),value=select.value;select.replaceChildren(option('','None'),...state.templates.map(item=>option(item.id,item.name)));select.value=value}
$('#taskTemplateSelect').addEventListener('change',event=>{const item=state.templates.find(candidate=>candidate.id===event.target.value);if(!item)return;$('#taskOptions').open=true;$('#taskTitle').value=item.title;$('#taskType').value=item.type||'personal';$('#taskSection').value=item.section;$('#taskProject').value=item.project||'';$('#taskRepository').value=item.repository||'';$('#taskPriority').value=item.priority||'normal';$('#taskRecurrence').value=item.recurrence||'';$('#taskSummary').value=item.summary||'';$('#checklistEditor').replaceChildren(...item.checklist.map(checklistRow))});
$('#saveTemplateButton').addEventListener('click',async()=>{const name=await appDialog({title:'Save as template',input:{label:'Template name',maxLength:100},confirmLabel:'Save template'});if(!name)return;try{const payload=taskFormPayload();delete payload.due_date;delete payload.defer_until;delete payload.visibility;await api('/api/v1/templates',{method:'POST',body:JSON.stringify({name:name.trim(),...payload})});const data=await api('/api/v1/templates');state.templates=data.templates||[];renderTemplateOptions()}catch(error){$('#taskError').textContent=error.message}});
$('#deleteTemplateButton').addEventListener('click',async()=>{const id=$('#taskTemplateSelect').value,item=state.templates.find(candidate=>candidate.id===id);if(!item){$('#taskError').textContent='Choose a template to delete.';return}if(!await appDialog({title:'Delete template',message:`Delete template “${item.name}”?`,confirmLabel:'Delete',danger:true}))return;try{await api(`/api/v1/templates/${id}`,{method:'DELETE'});state.templates=state.templates.filter(candidate=>candidate.id!==id);renderTemplateOptions()}catch(error){$('#taskError').textContent=error.message}});
$('#viewFilter').addEventListener('change',event=>setFilter(event.target.value));
