function notificationPreferences(){try{return JSON.parse(localStorage.getItem('taskboard-notifications'))||{}}catch{return {}}}
function loadSettings(){const value=notificationPreferences();$('#notifyProgress').checked=value.progress!==false;$('#notifyReminders').checked=value.reminders!==false;$('#notifySummaries').checked=Boolean(value.summaries)}
$('#settingsForm').addEventListener('submit',async event=>{event.preventDefault();const preferences={progress:$('#notifyProgress').checked,reminders:$('#notifyReminders').checked,summaries:$('#notifySummaries').checked};localStorage.setItem('taskboard-notifications',JSON.stringify(preferences));const endpoint=localStorage.getItem('taskboard-push-endpoint');try{if(endpoint)await api('/api/v1/push/subscriptions',{method:'PATCH',body:JSON.stringify({endpoint,...preferences})});settingsDialog.close()}catch(error){notificationMessage(error.message)}});
const notificationStates={checking:['…','Checking notifications'],enabling:['…','Enabling notifications'],on:['On','Notifications enabled on this device'],off:['Off','Notifications off. Enable notifications'],blocked:['Blocked','Notifications blocked. View instructions'],install:['Install','Install on your Home Screen to enable notifications'],unsupported:['Unavailable','Notifications unavailable. View instructions'],error:['Retry','Could not verify notifications. Retry'],signedOut:['Off','Sign in to enable notifications'],desktop:['Desktop','Test desktop notifications']};
function setNotificationState(value){
  const button=$('#notifyButton');const [label,description]=notificationStates[value];
  button.dataset.state=value;button.title=description;button.setAttribute('aria-label',description);
  button.disabled=['checking','enabling','signedOut'].includes(value);$('#notifyLabel').textContent=label;
}
function notificationMessage(message=''){const element=$('#notificationMessage');element.textContent=message;element.hidden=!message}
const pushClient=PWAKit.createPushClient({
  isAuthenticated:()=>state.authenticated,
  getPublicKey:async()=>(await api('/api/v1/push/key')).public_key,
  save:async subscription=>{const value=subscription.toJSON();localStorage.setItem('taskboard-push-endpoint',value.endpoint);await api('/api/v1/push/subscriptions',{method:'POST',body:JSON.stringify(value)});const preferences=notificationPreferences();await api('/api/v1/push/subscriptions',{method:'PATCH',body:JSON.stringify({endpoint:value.endpoint,progress:preferences.progress!==false,reminders:preferences.reminders!==false,summaries:Boolean(preferences.summaries)})})},
  onState:status=>{if(!window.__TAURI__?.core?.invoke)setNotificationState(status.status)}
});
function refreshNotificationState(){if(window.__TAURI__?.core?.invoke){setNotificationState('desktop');return}return pushClient.refresh()}
$('#notifyButton').addEventListener('click',async()=>{
  notificationMessage();
  if(window.__TAURI__?.core?.invoke){
    try{await window.__TAURI__.core.invoke('alert',{payload:{id:'enabled',title:'Taskboard notifications enabled',body:'You’ll be notified when agent work needs attention or finishes.',urgent:false}})}catch(error){notificationMessage(error.message)}
    return;
  }
  if(pushClient.state.status==='on'){notificationMessage('Notifications are enabled on this device. If alerts are missing, check Taskboard notification settings and Focus on your device.');return}
  const result=await pushClient.enable();notificationMessage(result.message);
});
