function registerWebMCP(){const context=document.modelContext;if(!context?.registerTool)return;const options={signal:new AbortController().signal};const report=error=>console.warn('WebMCP registration failed',error);Promise.resolve(context.registerTool({name:'list_taskboard_tasks',title:'List Taskboard tasks',description:'List the signed-in user’s visible private, team, and agent-pickup tasks, optionally filtered by status.',inputSchema:{type:'object',properties:{statuses:{type:'array',items:{type:'string',enum:['queued','active','waiting','blocked','stale','done','cancelled']}}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},async execute(input){const query=(input.statuses||[]).map(status=>`status=${encodeURIComponent(status)}`).join('&');const result={tasks:await fetchAllTasks(query)};return {tasks:result.tasks.map(task=>({id:task.id,title:task.title,type:task.type,visibility:task.visibility,section:sectionName(task),project:task.project,repository:task.repository,priority:task.priority,due_date:task.due_date,defer_until:task.defer_until,status:task.status,owner:task.owner,progress:progress(task),current_note:task.current_note,blocker:task.blocker,waiting_for:task.waiting_for}))}}},options)).catch(report);Promise.resolve(context.registerTool({name:'create_taskboard_task',title:'Capture Taskboard task',description:'Capture queued work without starting a person or agent run. New tasks default to private.',inputSchema:{type:'object',properties:{title:{type:'string',minLength:1,maxLength:200},type:{type:'string',enum:['personal','work']},visibility:{type:'string',enum:['private','team','agent']},summary:{type:'string',maxLength:2000},section:{type:'string',maxLength:80},project:{type:'string',maxLength:120},repository:{type:'string',maxLength:300},priority:{type:'string',enum:['low','normal','high','urgent']},due_date:{type:'string',format:'date'},defer_until:{type:'string',description:'YYYY-MM-DD, or an RFC 3339 timestamp; agent-pickup tasks are not offered before it'},recurrence:{type:'string',enum:['','daily','weekly','monthly']},checklist:{type:'array',maxItems:100,items:{type:'string',minLength:1,maxLength:300}}},required:['title'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input){const result=await captureTask(input);await load();return {task_id:result.task.id,type:result.task.type,visibility:result.task.visibility,status:result.task.status,section:sectionName(result.task),version:result.task.version}}},options)).catch(report)}
registerWebMCP();
async function initializeSession(){try{const session=await api('/api/v1/session');state.authenticated=Boolean(session.authenticated);state.identity=session.identity||'';state.principal=session.principal||'';state.role=session.role||'viewer';state.logoutURL=session.logout_url||'';state.taskType=session.task_type||'';state.routineProducers=session.routine_producers||[];if(new URLSearchParams(location.search).get('view')==='automatic'){state.filter='automatic';$('#viewFilter').value='automatic'};applyRoleControls();refreshNotificationState();if(!state.authenticated){setConnection('offline','Sign in');const button=$('#oidcLoginButton');button.hidden=!session.oidc_enabled;button.disabled=false;$('#loginCopy').textContent=session.cloudflare_access_enabled?'Authenticate through Cloudflare Access to continue.':'Use your organization account to continue.';$('#loginError').textContent=session.oidc_enabled||session.cloudflare_access_enabled?'':'Browser authentication is not configured.';if(!loginDialog.open)loginDialog.showModal();return}if(loginDialog.open)loginDialog.close();await load()}catch{setConnection('offline','Offline');setTimeout(initializeSession,5000)}}
initializeSession();

const scheduleOutcomes={created:'created a task',skipped_open_occurrence:'skipped (last task still open)',stopped_invalid_definition:'stopped: the definition no longer parses'};
function scheduleSplit(value){return value.split(/[,\s]+/).map(item=>item.trim()).filter(Boolean)}
function resetScheduleForm(){state.editingSchedule=null;$('#scheduleForm').reset();$('#scheduleID').value='';$('#scheduleVersion').value='';$('#scheduleTimezone').value=Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC';$('#scheduleEnabled').checked=true;$('#scheduleFormTitle').textContent='New schedule';$('#scheduleSubmit').textContent='Create schedule';$('#scheduleCancelEdit').hidden=true;$('#scheduleError').textContent=''}
function scheduleRequest(item,overrides={}){return {name:item.name,enabled:item.enabled,cron:item.cron,timezone:item.timezone,overlap:item.overlap,title:item.title,type:item.type,summary:item.summary||'',section:item.section,project:item.project||'',repository:item.repository||'',priority:item.priority,checklist:item.checklist||[],requirements:item.requirements||[],expected_version:item.version,...overrides}}
function editSchedule(item){resetScheduleForm();state.editingSchedule=item;$('#scheduleID').value=item.id;$('#scheduleVersion').value=item.version;$('#scheduleName').value=item.name;$('#scheduleTitle').value=item.title;$('#scheduleCron').value=item.cron;$('#scheduleTimezone').value=item.timezone;$('#scheduleOverlap').value=item.overlap;$('#scheduleEnabled').checked=item.enabled;$('#scheduleProject').value=item.project||'';$('#scheduleRepository').value=item.repository||'';$('#scheduleRequirements').value=(item.requirements||[]).join(', ');$('#scheduleSummary').value=item.summary||'';$('#scheduleChecklist').value=(item.checklist||[]).join('\n');$('#scheduleFormTitle').textContent=`Edit “${item.name}”`;$('#scheduleSubmit').textContent='Save schedule';$('#scheduleCancelEdit').hidden=false;$('#scheduleName').focus()}
async function scheduleAction(item,action,button){button.disabled=true;try{if(action==='run'){const result=await api(`/api/v1/schedules/${encodeURIComponent(item.id)}/run`,{method:'POST'});if(!result.task)await notify('The last task from this schedule is still open, so this run was skipped.');await load()}else if(action==='toggle'){await api(`/api/v1/schedules/${encodeURIComponent(item.id)}`,{method:'PUT',body:JSON.stringify(scheduleRequest(item,{enabled:!item.enabled}))})}else if(action==='delete'){if(!await appDialog({title:'Delete schedule',message:`Delete “${item.name}”? Tasks it already created are kept.`,confirmLabel:'Delete',danger:true}))return;await api(`/api/v1/schedules/${encodeURIComponent(item.id)}`,{method:'DELETE'});if($('#scheduleID').value===item.id)resetScheduleForm()}await loadSchedules()}catch(error){$('#schedulesStatus').textContent=error.message}finally{button.disabled=false}}
async function loadSchedules(){const status=$('#schedulesStatus'),list=$('#schedulesList');status.textContent='Loading…';$('#scheduleForm').hidden=!canWriteTasks();try{const items=(await api('/api/v1/schedules')).schedules||[];list.replaceChildren();status.textContent=items.length?'':'No schedules yet.';for(const item of items){const row=document.createElement('li');row.dataset.state=item.enabled?'active':'paused';const name=document.createElement('strong');name.textContent=item.enabled?item.name:`${item.name} · paused`;row.append(name);if(canWriteTasks())for(const [action,label] of [['run','Run now'],['edit','Edit'],['toggle',item.enabled?'Pause':'Resume'],['delete','Delete']]){const button=document.createElement('button');button.type='button';button.className='text-button';button.textContent=label;button.setAttribute('aria-label',`${label} ${item.name}`);button.addEventListener('click',()=>action==='edit'?editSchedule(item):scheduleAction(item,action,button));row.append(button)}const detail=document.createElement('small');detail.textContent=[`${item.cron} (${item.timezone})`,item.title,item.next_run_at?`next ${new Date(item.next_run_at).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})}`:'',item.last_run_at?`last run ${relativeTime(item.last_run_at)}: ${scheduleOutcomes[item.last_outcome]||item.last_outcome}`:'never run',(item.requirements||[]).length?`requires ${item.requirements.join(', ')}`:''].filter(Boolean).join(' · ');row.append(detail);list.append(row)}}catch(error){status.textContent=error.message}}
$('#schedulesButton').addEventListener('click',()=>{resetScheduleForm();schedulesDialog.showModal();loadSchedules()});
$('#scheduleCancelEdit').addEventListener('click',resetScheduleForm);
$('#scheduleForm').addEventListener('submit',async event=>{event.preventDefault();const id=$('#scheduleID').value,button=$('#scheduleSubmit');const payload={name:$('#scheduleName').value.trim(),enabled:$('#scheduleEnabled').checked,cron:$('#scheduleCron').value.trim(),timezone:$('#scheduleTimezone').value.trim(),overlap:$('#scheduleOverlap').value,title:$('#scheduleTitle').value.trim(),project:$('#scheduleProject').value.trim(),repository:$('#scheduleRepository').value.trim(),requirements:scheduleSplit($('#scheduleRequirements').value),summary:$('#scheduleSummary').value.trim(),checklist:$('#scheduleChecklist').value.split('\n').map(line=>line.trim()).filter(Boolean)};const body=id&&state.editingSchedule?scheduleRequest(state.editingSchedule,payload):payload;if(id)body.expected_version=Number($('#scheduleVersion').value);button.disabled=true;$('#scheduleError').textContent='';try{await api(id?`/api/v1/schedules/${encodeURIComponent(id)}`:'/api/v1/schedules',{method:id?'PUT':'POST',body:JSON.stringify(body)});resetScheduleForm();await loadSchedules()}catch(error){$('#scheduleError').textContent=error.message}finally{button.disabled=false}});
